class Countdown:
    def __init__(self, start):
        self.start = start

    def __iter__(self):
        # A generator method: every call to iter() starts a fresh, independent iterator.
        n = self.start
        while n > 0:
            yield n
            n -= 1


def chunked(iterable, n):
    # Validate eagerly: a generator function's body doesn't run until the first next().
    if n < 1:
        raise ValueError("n must be at least 1")
    return _chunks(iter(iterable), n)


def _chunks(it, n):
    chunk = []
    for item in it:
        chunk.append(item)
        if len(chunk) == n:
            yield chunk
            chunk = []
    if chunk:
        yield chunk
